import json
from taf.hw.hp.redfish.httpclient.ApiClient import ApiClient
from taf.hw.hp.redfish.httpclient.redfish_uri import AccountServiceURI
from taf.hw.hp.redfish.services.ViewOperation.views_common import ViewsCommon


class AccountCommon(object):
    def __init__(self, configuration, access_token):
        self.httpclient = ApiClient(configuration, access_token)

    def create_new_user_account(self, user_name, user_password, role_id="Administrator", check_status=None):
        if role_id not in ["Administrator", "Operator", "ReadOnly"]:
            raise ValueError(f"Unsuported role id {role_id}")
        uri = AccountServiceURI().create_user_uri
        data = {"Oem": {
            "Hpe": {
                "LoginName": user_name,
                "SkipEscCharsCheck": True,
                "ServiceAccount": False
                }
            },
        "UserName": user_name,
        "RoleId": role_id,
        "Password": user_password
        }
        return self.httpclient.send_post_request(uri=uri, check_status=check_status, data=json.dumps(data),
                                                 headers={"Content-Type": "application/json"})

    def modify_user_account_info(self, user_name, new_data, check_status=None):
        user_data = {
            "Select": [{
                "From": "/SessionService/Sessions/MySession/",
                "Properties": ["Oem.Hpe.Privileges.iLOConfigPriv AS iLOConfigPriv",
                               "Oem.Hpe.Privileges.UserConfigPriv AS UserConfigPriv",
                               "Oem.Hpe.Privileges.SystemRecoveryConfigPriv AS SystemRecoveryConfigPriv",
                               "Oem.Hpe.UserType AS UserType", "UserName", "Id AS SessionId"]
            },
            {
                "From": "/",
                "Properties": ["Oem.Hpe.Sessions.LDAPEnabled AS LDAPEnabled",
                               "Oem.Hpe.Sessions.LocalLoginEnabled AS LocalLoginEnabled"]
            },
            {
                "From": "/AccountService/",
                "Properties": ["Oem.Hpe AS AccountSettings"]
            },
            {
                "From": "/AccountService/Accounts/?$expand=.",
                "Properties": ["Members AS Accounts"]
            },
            {
                "From": "/AccountService/Roles/?$expand=.",
                "Properties": ["Members AS Roles"]
            }]
        }
        user_info_dict = ViewsCommon.get_info_from_redfish_views(self, data=user_data)
        for user_item in user_info_dict["Accounts"]:
            if user_item["UserName"] == user_name:
                uri = user_item["@odata.id"]
                break
        else:
            raise LookupError(f"User {user_name} is not exist!")
        return self.httpclient.send_patch_request(uri=uri, check_status=check_status, data=json.dumps(new_data),
                                                 headers={"Content-Type": "application/json"})

    def modify_user_password(self, user_name, new_password, check_status=None):
        new_data = {"Oem": {
                    "Hpe": {"SkipEscCharsCheck": True}
                },
                "Password": new_password}
        return self.modify_user_account_info(user_name, new_data=new_data, check_status=None)

    def delete_user_account(self, user_id, check_status=None):
        uri = AccountServiceURI().delete_user_uri
        return self.httpclient.send_delete_request(uri=uri.format(user_id=user_id), check_status=check_status,
                                                 headers={"Content-Type": "application/json"})
